GAME_HTML = '<!DOCTYPE html>\n<html lang="en"><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<style>\n:root{--bg:#07070f;--panel:#12122b;--neon:#00f0ff;--pink:#ff2bd6;--lime:#b6ff00;--text:#e8eaff;--dim:#8f94c4}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{height:100%;overflow:hidden;background:radial-gradient(circle at 50% 0%,#1b1250 0%,#07070f 65%);color:var(--text);font-family:"Trebuchet MS","Segoe UI",Arial,sans-serif;-webkit-user-select:none;user-select:none}\n#app{position:relative;height:100vh;display:flex;flex-direction:column;gap:8px;padding:8px}\n#hud{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}\n.chip{background:rgba(18,18,43,.9);border:1px solid rgba(0,240,255,.35);border-radius:10px;padding:4px 4px;text-align:center;box-shadow:0 0 12px rgba(0,240,255,.12)}\n.chip small{display:block;font-size:10px;color:var(--dim);letter-spacing:.08em}\n.chip b{font-size:16px;color:var(--neon);font-variant-numeric:tabular-nums}\n#stage{position:relative;flex:1;min-height:0}\n#game{width:100%;height:100%;object-fit:contain;background:#000;border-radius:14px;border:2px solid rgba(0,240,255,.45);box-shadow:0 0 26px rgba(0,240,255,.25),0 0 60px rgba(255,43,214,.12);outline:none}\n#controls{display:flex;flex-wrap:wrap;gap:6px;justify-content:center}\n.btn{font:inherit;font-weight:700;font-size:13px;color:#fff;border:0;border-radius:10px;padding:9px 14px;cursor:pointer;background:linear-gradient(135deg,#2a2a66,#1a1a44);border:1px solid rgba(0,240,255,.4);transition:transform .15s,box-shadow .15s,filter .15s}\n.btn:hover:not(:disabled){transform:translateY(-2px);box-shadow:0 6px 18px rgba(0,240,255,.3)}\n.btn:disabled{opacity:.35;cursor:not-allowed}\n.btn.go{background:linear-gradient(135deg,#00c2ff,#7b2dff);border-color:transparent}\n.btn.hot{background:linear-gradient(135deg,#ff2bd6,#ff6a00);border-color:transparent}\n.btn.big{font-size:17px;padding:13px 26px}\n#touch{display:none;justify-content:space-between;gap:8px}\n#touch .grp{display:flex;gap:8px}\n.tb{width:74px;height:54px;border-radius:14px;font-size:22px;color:#fff;border:1px solid rgba(0,240,255,.5);background:rgba(18,18,43,.9);touch-action:none}\n.tb.on{background:#00f0ff;color:#000}\n@media (pointer:coarse){#touch{display:flex}}\n.screen{position:absolute;inset:0;z-index:10;overflow:auto;background:rgba(5,5,16,.97);padding:16px;display:none;flex-direction:column;align-items:center;gap:12px;text-align:center}\n.screen.show{display:flex}\nh1.title{font-size:clamp(28px,6vw,54px);line-height:1.02;font-weight:900;letter-spacing:.02em;font-style:italic;background:linear-gradient(90deg,#00f0ff,#ff2bd6,#ffd400);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 14px rgba(255,43,214,.45))}\n.sub{color:var(--dim);font-size:14px;max-width:560px}\n.panel{background:var(--panel);border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:12px 16px;width:100%;max-width:620px;text-align:left;font-size:13.5px;line-height:1.55}\n.panel h3{font-size:14px;color:var(--neon);margin-bottom:4px}\n.panel ul{padding-left:18px}\nkbd{background:#222252;border:1px solid #4a4a99;border-bottom-width:2px;border-radius:5px;padding:0 6px;font-size:12px}\n.board{list-style:none;padding:0}\n.board li{display:flex;justify-content:space-between;gap:10px;padding:3px 0;border-bottom:1px dashed rgba(255,255,255,.08)}\n#grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;width:100%;max-width:900px}\n.card{background:var(--panel);border:2px solid rgba(255,255,255,.1);border-radius:14px;padding:8px;cursor:pointer;transition:transform .15s,border-color .15s,box-shadow .15s}\n.card:hover{transform:translateY(-3px)}\n.card.sel{border-color:var(--neon);box-shadow:0 0 18px rgba(0,240,255,.5)}\n.card canvas{width:100%;height:auto;border-radius:8px;background:radial-gradient(circle,#2a2a66,#0b0b22)}\n.cname{font-weight:800;font-size:13px;margin:4px 0}\n.bar{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--dim);margin:2px 0}\n.bar span{width:26px;text-align:left}\n.bar i{flex:1;height:6px;background:#23234d;border-radius:4px;overflow:hidden}\n.bar u{display:block;height:100%;background:linear-gradient(90deg,#00f0ff,#ff2bd6)}\n#pickbar{position:sticky;bottom:0;padding:10px;background:linear-gradient(transparent,#050510 40%);width:100%;display:flex;gap:8px;justify-content:center;flex-wrap:wrap}\n.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;width:100%;max-width:620px}\n.stat{background:var(--panel);border-radius:10px;padding:8px;border:1px solid rgba(255,255,255,.1)}\n.stat small{display:block;color:var(--dim);font-size:11px}\n.stat b{font-size:19px;color:var(--lime)}\n.badge{display:inline-block;padding:4px 12px;border-radius:99px;background:linear-gradient(90deg,#ffd400,#ff6a00);color:#000;font-weight:900;font-size:13px}\n.grade{font-size:46px;font-weight:900;color:var(--lime);text-shadow:0 0 18px rgba(182,255,0,.6)}\n</style></head>\n<body>\n<div id="app">\n  <div id="hud">\n    <div class="chip"><small>SPEED</small><b id="hSpeed">0</b></div>\n    <div class="chip"><small>DISTANCE</small><b id="hDist">0 m</b></div>\n    <div class="chip"><small>LAP</small><b id="hLap">1/3</b></div>\n    <div class="chip"><small>TIME</small><b id="hTime">0:00.0</b></div>\n    <div class="chip"><small>SCORE</small><b id="hScore">0</b></div>\n    <div class="chip"><small>LIVES</small><b id="hLives">3</b></div>\n  </div>\n  <div id="stage">\n    <canvas id="game" tabindex="0"></canvas>\n\n    <div id="home" class="screen show">\n      <h1 class="title">ULTIMATE<br>STREET RACER</h1>\n      <p class="sub">Pick one of 20 cars, race 3 laps, dodge traffic and obstacles, and climb the leaderboard.</p>\n      <div class="panel"><h3>How to play</h3>\n        <ul>\n          <li><kbd>&larr;</kbd> <kbd>&rarr;</kbd> steer (or <kbd>A</kbd> <kbd>D</kbd>), <kbd>&uarr;</kbd> accelerate, <kbd>&darr;</kbd> brake, <kbd>P</kbd> pause.</li>\n          <li>On a phone, use the on-screen buttons below the track.</li>\n          <li>You have 3 lives. Hitting cones, barrels or traffic costs one life.</li>\n          <li>Score: +25 per car passed, +10 per obstacle avoided, +500 per lap, points for speed, plus a finish bonus.</li>\n          <li>Traffic gets faster and denser every level.</li>\n        </ul>\n      </div>\n      <div class="panel"><h3>High score: <span id="hiHome">0</span></h3><ul class="board" id="boardHome"></ul></div>\n      <button class="btn go big" id="toSelect">CHOOSE YOUR CAR</button>\n    </div>\n\n    <div id="select" class="screen">\n      <h1 class="title" style="font-size:clamp(22px,4vw,34px)">CHOOSE YOUR CAR</h1>\n      <div id="grid"></div>\n      <div id="pickbar"><button class="btn" id="backHome">Back</button><button class="btn hot big" id="confirmCar">RACE</button></div>\n    </div>\n\n    <div id="result" class="screen">\n      <div id="resTitle" class="title" style="font-size:clamp(26px,5vw,44px);font-weight:900;font-style:italic"></div>\n      <div id="resBadge"></div>\n      <div class="grade" id="resGrade"></div>\n      <p class="sub" id="resMsg"></p>\n      <div class="stats" id="resStats"></div>\n      <div class="panel"><h3>Leaderboard</h3><ul class="board" id="boardRes"></ul></div>\n      <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center">\n        <button class="btn go big" id="resRestart">Restart race</button>\n        <button class="btn big" id="resNew">New race</button>\n      </div>\n    </div>\n  </div>\n\n  <div id="touch">\n    <div class="grp"><button class="tb" id="tLeft">&#9664;</button><button class="tb" id="tRight">&#9654;</button></div>\n    <div class="grp"><button class="tb" id="tBrake">&#9632;</button><button class="tb" id="tGas">&#9650;</button></div>\n  </div>\n\n  <div id="controls">\n    <button class="btn go" id="bStart" disabled>Start</button>\n    <button class="btn" id="bPause" disabled>Pause</button>\n    <button class="btn" id="bResume" disabled>Resume</button>\n    <button class="btn" id="bRestart" disabled>Restart</button>\n    <button class="btn hot" id="bNew">New Race</button>\n  </div>\n</div>\n\n<script>\n(function(){\n\'use strict\';\nvar CARS=__CARS_JSON__;\nvar TOTAL_LAPS=3, LAP_LEN=2400, TOTAL=TOTAL_LAPS*LAP_LEN;\nvar W=640,H=420,HOR=140,PY=340,D=16,KMH=2.1,LANES=[-0.75,0,0.75];\nvar $=function(id){return document.getElementById(id);};\nvar cv=$(\'game\'), ctx=cv.getContext(\'2d\');\ncv.width=W; cv.height=H;\n\nvar state=\'menu\', prevState=\'racing\', selected=0, G=null, raf=null, last=0;\nvar keys={left:false,right:false,up:false,down:false};\n\n/* ---------- helpers ---------- */\nfunction clamp(v,a,b){return v<a?a:(v>b?b:v);}\nfunction curveX(z){return Math.sin(z/300)*0.8+Math.sin(z/110)*0.15;}\nfunction hash(n){var s=Math.sin(n*12.9898)*43758.5453;return s-Math.floor(s);}\nfunction fmtTime(t){var m=Math.floor(t/60),s=t-m*60;return m+\':\'+(s<10?\'0\':\'\')+s.toFixed(1);}\nfunction difficulty(){return 1+(G?G.z:0)/1100;}\nvar STARS=[];for(var si=0;si<70;si++){STARS.push({x:Math.random()*W,y:Math.random()*(HOR-30),a:0.3+Math.random()*0.7});}\n\n/* ---------- leaderboard (localStorage with in-memory fallback) ---------- */\nvar memBoard=[];\nfunction loadBoard(){try{var s=localStorage.getItem(\'usr_board_v1\');if(s)return JSON.parse(s);}catch(e){}return memBoard;}\nfunction saveBoard(b){memBoard=b;try{localStorage.setItem(\'usr_board_v1\',JSON.stringify(b));}catch(e){}}\nfunction addScore(entry){var b=loadBoard();b.push(entry);b.sort(function(a,c){return c.score-a.score;});saveBoard(b.slice(0,8));}\nfunction highScore(){var b=loadBoard();return b.length?b[0].score:0;}\nfunction renderBoards(){\n  var b=loadBoard();\n  var h=b.length?b.map(function(e,i){return \'<li><span>\'+(i+1)+\'. \'+e.car+(e.ok?\'\':\' (crashed)\')+\'</span><span>\'+e.score+\' pts &middot; \'+fmtTime(e.time)+\'</span></li>\';}).join(\'\'):\'<li>No races yet. Be the first!</li>\';\n  $(\'boardHome\').innerHTML=h; $(\'boardRes\').innerHTML=h; $(\'hiHome\').textContent=highScore();\n}\n\n/* ---------- drawing: cars ---------- */\nfunction rr(g,x,y,w,h,r){g.beginPath();g.moveTo(x+r,y);g.arcTo(x+w,y,x+w,y+h,r);g.arcTo(x+w,y+h,x,y+h,r);g.arcTo(x,y+h,x,y,r);g.arcTo(x,y,x+w,y,r);g.closePath();}\nfunction bodyFill(g,c,x,w){\n  if(c.rainbow){var gr=g.createLinearGradient(x,0,x+w,0);[\'#ff0040\',\'#ff9500\',\'#ffee00\',\'#00e676\',\'#00b0ff\',\'#b400ff\'].forEach(function(col,i,a){gr.addColorStop(i/(a.length-1),col);});return gr;}\n  return c.color;\n}\nfunction drawCar(g,c,cx,by,w,alpha){\n  var h=w*0.62,x=cx-w/2,y=by-h;\n  g.save(); if(alpha!=null)g.globalAlpha=alpha;\n  g.fillStyle=\'rgba(0,0,0,.38)\';g.beginPath();g.ellipse(cx,by,w*0.56,w*0.08,0,0,7);g.fill();\n  var ww=w*0.17,wh=h*0.36;\n  g.fillStyle=\'#0b0b10\';rr(g,x-ww*0.25,by-wh,ww,wh,w*0.03);g.fill();rr(g,x+w-ww*0.75,by-wh,ww,wh,w*0.03);g.fill();\n  g.fillStyle=c.accent;rr(g,x+w*0.1,y+h*0.14,w*0.8,h*0.1,w*0.03);g.fill();            /* spoiler */\n  g.fillStyle=bodyFill(g,c,x,w);rr(g,x+w*0.14,y,w*0.72,h*0.5,w*0.14);g.fill();         /* cabin */\n  rr(g,x,y+h*0.3,w,h*0.6,w*0.1);g.fill();                                              /* body */\n  g.fillStyle=\'#0c1424\';rr(g,x+w*0.22,y+h*0.07,w*0.56,h*0.3,w*0.07);g.fill();         /* rear glass */\n  g.fillStyle=\'rgba(120,200,255,.25)\';rr(g,x+w*0.25,y+h*0.1,w*0.2,h*0.12,w*0.03);g.fill();\n  g.fillStyle=c.accent;g.fillRect(cx-w*0.04,y+h*0.42,w*0.08,h*0.26);                    /* trunk stripe */\n  g.fillStyle=\'#ff2030\';g.shadowColor=\'#ff2030\';g.shadowBlur=w*0.12;\n  rr(g,x+w*0.06,y+h*0.5,w*0.24,h*0.12,w*0.03);g.fill();rr(g,x+w*0.7,y+h*0.5,w*0.24,h*0.12,w*0.03);g.fill();\n  g.shadowBlur=0;\n  g.fillStyle=\'#f2f2f2\';rr(g,cx-w*0.1,y+h*0.68,w*0.2,h*0.1,w*0.01);g.fill();           /* plate */\n  g.fillStyle=\'#111\';rr(g,x+w*0.04,y+h*0.84,w*0.92,h*0.1,w*0.04);g.fill();             /* bumper */\n  g.restore();\n}\nfunction drawCone(g,px,by,w){\n  var h=w*1.1;g.fillStyle=\'rgba(0,0,0,.3)\';g.beginPath();g.ellipse(px,by,w*0.5,w*0.1,0,0,7);g.fill();\n  g.fillStyle=\'#ff6a00\';g.beginPath();g.moveTo(px-w*0.4,by);g.lineTo(px+w*0.4,by);g.lineTo(px+w*0.08,by-h);g.lineTo(px-w*0.08,by-h);g.closePath();g.fill();\n  g.fillStyle=\'#fff\';g.fillRect(px-w*0.24,by-h*0.55,w*0.48,h*0.15);\n  g.fillStyle=\'#222\';g.fillRect(px-w*0.46,by-h*0.07,w*0.92,h*0.09);\n}\nfunction drawBarrel(g,px,by,w){\n  var h=w*1.25;g.fillStyle=\'rgba(0,0,0,.3)\';g.beginPath();g.ellipse(px,by,w*0.55,w*0.1,0,0,7);g.fill();\n  g.fillStyle=\'#2266ff\';rr(g,px-w*0.45,by-h,w*0.9,h,w*0.12);g.fill();\n  g.fillStyle=\'#ffd400\';g.fillRect(px-w*0.45,by-h*0.72,w*0.9,h*0.12);g.fillRect(px-w*0.45,by-h*0.32,w*0.9,h*0.12);\n}\n\n/* ---------- game state ---------- */\nfunction newGame(){\n  var c=CARS[selected];\n  G={car:c,z:0,x:0,speed:0,maxSpeed:60+c.speed*7,acc:22+c.accel*4.2,hand:1.1+c.handling*0.16,\n     time:0,score:0,lives:3,invuln:0,shake:0,scrape:0,steer:0,objs:[],lapsDone:0,lap:1,level:1,\n     crashes:0,passed:0,topSpeed:0,countdown:3.2,toast:\'\',toastT:0};\n  for(var i=0;i<7;i++)spawn(60,330);\n}\nfunction attractGame(){newGame();G.objs=[];}\nfunction toast(m){if(G){G.toast=m;G.toastT=1.6;}}\nfunction spawn(zmin,zmax){\n  if(!G)return;\n  for(var tries=0;tries<6;tries++){\n    var z=zmin+Math.random()*(zmax-zmin);\n    if(z>TOTAL-8)return;\n    var li=Math.floor(Math.random()*3), x=LANES[li]+(Math.random()-0.5)*0.12;\n    var blocked={},tooClose=false;\n    for(var k=0;k<G.objs.length;k++){var o=G.objs[k];\n      if(Math.abs(o.z-z)<16){blocked[Math.round(o.x/0.75)]=1;if(Math.abs(o.z-z)<9&&Math.abs(o.x-x)<0.6)tooClose=true;}}\n    blocked[li-1]=1;\n    if(tooClose||Object.keys(blocked).length>2)continue;\n    var diff=difficulty(),r=Math.random(),n;\n    if(r<0.55){\n      var ci;do{ci=Math.floor(Math.random()*CARS.length);}while(CARS[ci]===G.car);\n      n={type:\'opp\',car:CARS[ci],z:z,x:x,tx:x,speed:30+Math.random()*26+Math.min(38,diff*3.2),wt:1+Math.random()*3,weave:Math.min(0.7,0.1+diff*0.07)};\n    }else{n={type:r<0.8?\'cone\':\'barrel\',z:z,x:x,speed:0};}\n    G.objs.push(n);return;\n  }\n}\n\n/* ---------- state changes ---------- */\nfunction showScreen(name){\n  var all=document.querySelectorAll(\'.screen\');for(var i=0;i<all.length;i++)all[i].classList.remove(\'show\');\n  if(name)$(name).classList.add(\'show\');\n}\nfunction focusGame(){try{window.focus();cv.focus();}catch(e){}}\nfunction startRace(){if(state!==\'ready\')return;G.countdown=3.2;state=\'countdown\';showScreen(null);focusGame();buttons();}\nfunction restartRace(){if(state===\'menu\'||state===\'select\')return;newGame();state=\'countdown\';showScreen(null);focusGame();buttons();}\nfunction pauseRace(){if(state===\'racing\'||state===\'countdown\'){prevState=state;state=\'paused\';buttons();}}\nfunction resumeRace(){if(state===\'paused\'){state=prevState||\'racing\';focusGame();buttons();}}\nfunction newRace(){state=\'select\';attractGame();showScreen(\'select\');buttons();}\nfunction endRace(ok){\n  var prevHigh=highScore();\n  if(ok){var bonus=1000+Math.max(0,Math.round((150-G.time)*10))+G.lives*200;G.score+=bonus;G.bonus=bonus;}\n  G.score=Math.floor(G.score);\n  state=ok?\'finished\':\'over\';\n  addScore({car:G.car.name,score:G.score,time:G.time,ok:ok});\n  var grade=!ok?\'-\':(G.crashes===0?\'S\':(G.crashes===1?\'A\':(G.crashes===2?\'B\':\'C\')));\n  $(\'resTitle\').textContent=ok?\'RACE COMPLETE!\':\'GAME OVER\';\n  $(\'resBadge\').innerHTML=G.score>prevHigh?\'<span class="badge">NEW HIGH SCORE!</span>\':\'\';\n  $(\'resGrade\').textContent=ok?(\'Grade \'+grade):\'\';\n  $(\'resMsg\').textContent=ok?(G.crashes===0?\'Flawless driving. Not a scratch on the \'+G.car.name+\'!\':\'You crossed the finish line with \'+G.lives+\' \'+(G.lives===1?\'life\':\'lives\')+\' left.\'):\'You ran out of lives. Try another line or pick a car with better handling.\';\n  var avg=G.time>0?Math.round(G.z/G.time*KMH):0;\n  var st=[[\'Score\',G.score],[\'Time\',fmtTime(G.time)],[\'Distance\',Math.floor(G.z)+\' m\'],[\'Top speed\',Math.round(G.topSpeed*KMH)+\' km/h\'],[\'Avg speed\',avg+\' km/h\'],[\'Passed\',G.passed],[\'Crashes\',G.crashes],[\'Car\',G.car.name]];\n  $(\'resStats\').innerHTML=st.map(function(s){return \'<div class="stat"><small>\'+s[0]+\'</small><b>\'+s[1]+\'</b></div>\';}).join(\'\');\n  renderBoards();showScreen(\'result\');buttons();\n}\nfunction buttons(){\n  $(\'bStart\').disabled=state!==\'ready\';\n  $(\'bPause\').disabled=!(state===\'racing\'||state===\'countdown\');\n  $(\'bResume\').disabled=state!==\'paused\';\n  $(\'bRestart\').disabled=(state===\'menu\'||state===\'select\');\n}\n\n/* ---------- update ---------- */\nfunction update(dt){\n  if(!G)return;\n  if(state===\'menu\'||state===\'select\'){G.z+=45*dt;return;}\n  if(state===\'countdown\'){G.countdown-=dt;if(G.countdown<=0){state=\'racing\';toast(\'GO!\');buttons();}return;}\n  if(state!==\'racing\')return;\n  G.time+=dt;\n  if(keys.up)G.speed+=G.acc*dt*(1-0.5*G.speed/G.maxSpeed);\n  if(keys.down)G.speed-=95*dt;\n  if(!keys.up&&!keys.down)G.speed-=9*dt;\n  var steerIn=(keys.right?1:0)-(keys.left?1:0);\n  G.steer+=(steerIn-G.steer)*Math.min(1,10*dt);\n  var sens=G.hand*(0.35+0.65*Math.min(1,G.speed/40));\n  G.x+=G.steer*sens*dt;\n  G.scrape=Math.max(0,G.scrape-dt);\n  if(Math.abs(G.x)>1.0){G.speed-=26*dt;if(G.speed>20)G.scrape=0.15;}  /* rumble strip / barrier scrape */\n  G.x=clamp(G.x,-1.1,1.1);\n  G.speed=clamp(G.speed,0,G.maxSpeed);\n  G.topSpeed=Math.max(G.topSpeed,G.speed);\n  G.z+=G.speed*dt;\n  G.score+=G.speed*dt*0.12;\n  G.invuln=Math.max(0,G.invuln-dt);G.shake=Math.max(0,G.shake-dt);G.toastT=Math.max(0,G.toastT-dt);\n\n  var diff=difficulty(),lvl=Math.floor(diff);\n  if(lvl>G.level){G.level=lvl;toast(\'LEVEL \'+lvl+\' - FASTER TRAFFIC!\');}\n  var ahead=0;for(var i=0;i<G.objs.length;i++)if(G.objs[i].z-G.z>30)ahead++;\n  var target=Math.min(15,5+Math.floor(diff*1.3));\n  if(ahead<target&&Math.random()<dt*7)spawn(G.z+110,G.z+190);\n\n  for(var j=0;j<G.objs.length;j++){var o=G.objs[j];\n    if(o.type===\'opp\'){\n      o.z+=o.speed*dt;o.wt-=dt;\n      if(o.wt<=0){o.wt=2+Math.random()*3;if(Math.random()<o.weave)o.tx=LANES[Math.floor(Math.random()*3)];}\n      o.x+=clamp(o.tx-o.x,-0.35*dt,0.35*dt);\n    }\n    var dz=o.z-G.z,dx=Math.abs(o.x-G.x);\n    var hz=o.type===\'opp\'?2.3:1.6,hx=o.type===\'opp\'?0.46:0.38;\n    if(!o.dead&&G.invuln<=0&&Math.abs(dz)<hz&&dx<hx){crash(o);if(state!==\'racing\')return;}\n    if(!o.dead&&!o.passed&&dz<-2.5){o.passed=true;if(o.type===\'opp\'){G.score+=25;G.passed++;}else{G.score+=10;}}\n  }\n  G.objs=G.objs.filter(function(o){return !o.dead&&o.z>G.z-14;});\n\n  var done=Math.floor(G.z/LAP_LEN);\n  if(done>G.lapsDone&&done<TOTAL_LAPS){G.lapsDone=done;G.score+=500;toast(\'LAP \'+done+\' COMPLETE  +500\');}\n  G.lap=Math.min(TOTAL_LAPS,done+1);\n  if(G.z>=TOTAL){G.z=TOTAL;endRace(true);}\n}\nfunction crash(o){\n  o.dead=true;G.lives--;G.crashes++;G.invuln=1.8;G.speed*=0.25;G.shake=0.5;toast(\'CRASH!\');\n  if(G.lives<=0){G.lives=0;endRace(false);}\n}\n\n/* ---------- render ---------- */\nfunction drawSky(g,S){\n  var sky=g.createLinearGradient(0,0,0,HOR);sky.addColorStop(0,\'#05051a\');sky.addColorStop(0.6,\'#3a1a7a\');sky.addColorStop(1,\'#ff4f9a\');\n  g.fillStyle=sky;g.fillRect(0,0,W,HOR+2);\n  for(var i=0;i<STARS.length;i++){var s=STARS[i];g.fillStyle=\'rgba(255,255,255,\'+s.a+\')\';g.fillRect(s.x,s.y,1.5,1.5);}\n  var sx=W/2+curveX(S.z)*60;\n  var rg=g.createRadialGradient(sx,HOR-26,4,sx,HOR-26,60);rg.addColorStop(0,\'#fff3b0\');rg.addColorStop(0.35,\'#ffb347\');rg.addColorStop(1,\'rgba(255,79,154,0)\');\n  g.fillStyle=rg;g.fillRect(sx-70,HOR-96,140,140);\n  var sc=curveX(S.z)*80;g.fillStyle=\'#1a0f3a\';g.beginPath();g.moveTo(0,HOR);\n  for(var x=0;x<=W;x+=16){g.lineTo(x,HOR-18-14*Math.abs(Math.sin((x+sc)/70))-10*Math.sin((x+sc)/23));}\n  g.lineTo(W,HOR);g.closePath();g.fill();\n}\nfunction drawRoad(g,S){\n  var cs=curveX(S.z);\n  for(var y=HOR;y<H;y++){\n    var tt=(y-HOR+0.5)/(PY-HOR),dz=D*(1/tt-1),zA=S.z+dz;\n    var cx=W/2+(curveX(zA)-cs)*70*(1-Math.min(1,tt));\n    var hw=260*tt,band=Math.floor(zA/7)&1,cb=Math.floor(zA/4)&1;\n    g.fillStyle=band?\'#0e6b2e\':\'#0b5a26\';g.fillRect(0,y,W,1);\n    g.fillStyle=band?\'#dfe3ff\':\'#2f62ff\';g.fillRect(cx-hw*1.08,y,hw*0.08,1);g.fillRect(cx+hw*1.0,y,hw*0.08,1);\n    g.fillStyle=cb?\'#e10600\':\'#ffffff\';g.fillRect(cx-hw*1.0,y,hw*0.07,1);g.fillRect(cx+hw*0.93,y,hw*0.07,1);\n    g.fillStyle=band?\'#2a2a3c\':\'#303044\';g.fillRect(cx-hw*0.93,y,hw*1.86,1);\n    if((Math.floor(zA/5)&1)===0){g.fillStyle=\'rgba(255,255,255,.85)\';g.fillRect(cx-hw*0.27-hw*0.01,y,hw*0.02,1);g.fillRect(cx+hw*0.27-hw*0.01,y,hw*0.02,1);}\n    g.fillStyle=\'rgba(255,212,0,.8)\';g.fillRect(cx-hw*0.9,y,hw*0.014,1);g.fillRect(cx+hw*0.886,y,hw*0.014,1);\n    var lz=Math.round(zA/LAP_LEN)*LAP_LEN;\n    if(lz>=0&&lz<=TOTAL&&zA>=lz&&zA<lz+4){\n      var cell=hw*1.86/14,k0=Math.floor(zA-lz);\n      for(var c=0;c<14;c++){g.fillStyle=((c+k0)&1)?\'#ffffff\':\'#111111\';g.fillRect(cx-hw*0.93+c*cell,y,cell+0.5,1);}\n    }\n  }\n  var hz=g.createLinearGradient(0,HOR,0,HOR+26);hz.addColorStop(0,\'rgba(255,79,154,.55)\');hz.addColorStop(1,\'rgba(255,79,154,0)\');\n  g.fillStyle=hz;g.fillRect(0,HOR,W,26);\n}\nfunction drawScenery(g,S){\n  var step=10,base=Math.floor(S.z/step),cs=curveX(S.z);\n  for(var i=70;i>=1;i--){\n    var zA=(base+i)*step,dz=zA-S.z;if(dz<1)continue;\n    var t=1/(1+dz/D),y=HOR+(PY-HOR)*t,hw=260*t,cx=W/2+(curveX(zA)-cs)*70*(1-t);\n    for(var sd=-1;sd<=1;sd+=2){\n      var k=hash(zA*(sd+3));if(k<0.35)continue;\n      var px=cx+sd*hw*(1.35+k*0.9),s=t*(60+k*50);\n      if(k>0.92){\n        var col=(Math.floor(zA/step)&1)?\'0,240,255\':\'255,43,214\';\n        g.fillStyle=\'#333\';g.fillRect(px-s*0.02,y-s*1.1,s*0.04,s*1.1);\n        g.fillStyle=\'rgba(\'+col+\',.25)\';g.beginPath();g.arc(px,y-s*1.1,s*0.22,0,7);g.fill();\n        g.fillStyle=\'rgb(\'+col+\')\';g.beginPath();g.arc(px,y-s*1.1,s*0.09,0,7);g.fill();\n      }else{\n        g.fillStyle=\'#4a2c12\';g.fillRect(px-s*0.06,y-s*0.25,s*0.12,s*0.25);\n        for(var l=0;l<3;l++){g.fillStyle=l%2?\'#10964a\':\'#0c7a3a\';var ty=y-s*0.2-l*s*0.32,tw=s*(0.5-l*0.12);\n          g.beginPath();g.moveTo(px-tw,ty);g.lineTo(px+tw,ty);g.lineTo(px,ty-s*0.45);g.closePath();g.fill();}\n      }\n    }\n  }\n}\nfunction objX(S,o,t){return W/2+(curveX(o.z)-curveX(S.z))*70*(1-Math.min(1,t))+o.x*0.72*260*t;}\nfunction drawEntities(g,S){\n  var list=S.objs.filter(function(o){var d=o.z-S.z;return d>-5&&d<420;}).sort(function(a,b){return b.z-a.z;});\n  var drawn=false;\n  function player(){\n    var px=W/2+S.x*0.72*260,blink=S.invuln>0&&(Math.floor(S.invuln*10)%2===0);\n    g.save();g.translate(px,PY);g.rotate(S.steer*0.05);drawCar(g,S.car,0,0,100,blink?0.35:1);g.restore();\n    if(S.scrape>0){g.fillStyle=\'#ffd24a\';for(var i=0;i<6;i++){g.fillRect(px+(S.x>0?1:-1)*(52+Math.random()*8),PY-Math.random()*30,3,3);}}\n  }\n  for(var i=0;i<list.length;i++){\n    var o=list[i],dz=o.z-S.z;\n    if(!drawn&&dz<=0){player();drawn=true;}\n    var t=1/(1+dz/D);if(t<0.02)continue;\n    var by=HOR+(PY-HOR)*t,px2=objX(S,o,t);\n    if(o.type===\'opp\')drawCar(g,o.car,px2,by,100*t);\n    else if(o.type===\'cone\')drawCone(g,px2,by,46*t);\n    else drawBarrel(g,px2,by,54*t);\n  }\n  if(!drawn)player();\n}\nfunction drawHUD(g,S){\n  var p=clamp(S.z/TOTAL,0,1);\n  g.fillStyle=\'rgba(0,0,0,.5)\';g.fillRect(16,10,W-32,8);g.fillStyle=\'#00f0ff\';g.fillRect(16,10,(W-32)*p,8);\n  g.fillStyle=\'#fff\';for(var i=1;i<TOTAL_LAPS;i++)g.fillRect(16+(W-32)*i/TOTAL_LAPS-1,8,2,12);\n  g.textAlign=\'right\';g.font=\'bold 13px Trebuchet MS, Arial\';g.fillStyle=\'#ffd400\';g.fillText(\'LEVEL \'+Math.floor(difficulty()),W-18,38);\n  var cx=76,cy=H-48,r=42;\n  g.fillStyle=\'rgba(8,8,24,.78)\';g.beginPath();g.arc(cx,cy,r+8,0,7);g.fill();\n  g.lineWidth=7;g.lineCap=\'round\';g.strokeStyle=\'rgba(255,255,255,.13)\';g.beginPath();g.arc(cx,cy,r,0.75*Math.PI,2.25*Math.PI);g.stroke();\n  var f=clamp(S.speed/S.maxSpeed,0,1);\n  if(f>0.01){g.strokeStyle=\'hsl(\'+(170-f*170)+\',100%,55%)\';g.beginPath();g.arc(cx,cy,r,0.75*Math.PI,(0.75+1.5*f)*Math.PI);g.stroke();}\n  g.textAlign=\'center\';g.fillStyle=\'#fff\';g.font=\'bold 22px Trebuchet MS, Arial\';g.fillText(Math.round(S.speed*KMH),cx,cy+6);\n  g.font=\'10px Trebuchet MS, Arial\';g.fillStyle=\'#8fd8ff\';g.fillText(\'KM/H\',cx,cy+20);\n  if(S.toastT>0){g.globalAlpha=Math.min(1,S.toastT);g.font=\'bold 30px Trebuchet MS, Arial\';g.fillStyle=\'#fff\';g.shadowColor=\'#ff2bd6\';g.shadowBlur=16;g.fillText(S.toast,W/2,120);g.shadowBlur=0;g.globalAlpha=1;}\n  if(state===\'countdown\'){var n=Math.ceil(S.countdown-0.2);g.font=\'bold 90px Trebuchet MS, Arial\';g.fillStyle=\'#00f0ff\';g.shadowColor=\'#00f0ff\';g.shadowBlur=24;g.fillText(n>0?n:\'GO!\',W/2,230);g.shadowBlur=0;}\n  if(state===\'ready\'||state===\'paused\'){\n    g.fillStyle=\'rgba(0,0,10,.55)\';g.fillRect(0,0,W,H);g.fillStyle=\'#fff\';g.font=\'bold 34px Trebuchet MS, Arial\';\n    g.fillText(state===\'paused\'?\'PAUSED\':\'READY: \'+S.car.name,W/2,200);\n    g.font=\'16px Trebuchet MS, Arial\';g.fillStyle=\'#8fd8ff\';\n    g.fillText(state===\'paused\'?\'Press P or Resume to continue\':\'Press Start or Enter\',W/2,232);\n  }\n}\nfunction render(){\n  if(!G)return;\n  var g=ctx;g.save();\n  if(G.shake>0)g.translate((Math.random()-0.5)*10*G.shake,(Math.random()-0.5)*10*G.shake);\n  drawSky(g,G);drawRoad(g,G);drawScenery(g,G);drawEntities(g,G);\n  g.restore();drawHUD(g,G);\n  $(\'hSpeed\').textContent=Math.round(G.speed*KMH);\n  $(\'hDist\').textContent=Math.floor(G.z)+\' m\';\n  $(\'hLap\').textContent=G.lap+\'/\'+TOTAL_LAPS;\n  $(\'hTime\').textContent=fmtTime(G.time);\n  $(\'hScore\').textContent=Math.floor(G.score);\n  $(\'hLives\').textContent=G.lives>0?new Array(G.lives+1).join(\'\\u2764\'):\'0\';\n}\n\n/* ---------- single animation loop ---------- */\nfunction loop(ts){\n  raf=requestAnimationFrame(loop);\n  var dt=Math.min(0.05,(ts-last)/1000||0);last=ts;\n  try{update(dt);render();}catch(err){console.error(err);}\n}\nfunction startLoop(){if(raf!==null)return;last=performance.now();raf=requestAnimationFrame(loop);}\n\n/* ---------- select screen ---------- */\nfunction bar(l,v){return \'<div class="bar"><span>\'+l+\'</span><i><u style="width:\'+(v*10)+\'%"></u></i></div>\';}\nfunction buildSelect(){\n  var grid=$(\'grid\');grid.innerHTML=\'\';\n  CARS.forEach(function(c,i){\n    var d=document.createElement(\'div\');d.className=\'card\';d.setAttribute(\'data-i\',i);\n    var cvs=document.createElement(\'canvas\');cvs.width=160;cvs.height=100;\n    var nm=document.createElement(\'div\');nm.className=\'cname\';nm.textContent=(i+1)+\'. \'+c.name;\n    var bs=document.createElement(\'div\');bs.innerHTML=bar(\'SPD\',c.speed)+bar(\'ACC\',c.accel)+bar(\'HND\',c.handling);\n    d.appendChild(cvs);d.appendChild(nm);d.appendChild(bs);\n    d.addEventListener(\'click\',function(){pick(i);});\n    grid.appendChild(d);drawCar(cvs.getContext(\'2d\'),c,80,92,110);\n  });\n  pick(0);\n}\nfunction pick(i){\n  selected=i;\n  var cards=document.querySelectorAll(\'.card\');\n  for(var k=0;k<cards.length;k++)cards[k].classList.toggle(\'sel\',k===i);\n  $(\'confirmCar\').textContent=\'RACE WITH \'+CARS[i].name.toUpperCase();\n}\nfunction confirmCar(){newGame();state=\'ready\';showScreen(null);focusGame();buttons();}\n\n/* ---------- input ---------- */\nvar KEYMAP={ArrowLeft:\'left\',ArrowRight:\'right\',ArrowUp:\'up\',ArrowDown:\'down\',a:\'left\',A:\'left\',d:\'right\',D:\'right\',w:\'up\',W:\'up\',s:\'down\',S:\'down\'};\nwindow.addEventListener(\'keydown\',function(e){\n  var k=KEYMAP[e.key];\n  if(k){keys[k]=true;if(e.key.indexOf(\'Arrow\')===0)e.preventDefault();}\n  if(e.key===\'p\'||e.key===\'P\'||e.key===\'Escape\'){if(state===\'paused\')resumeRace();else pauseRace();}\n  if(e.key===\'Enter\'&&state===\'ready\'){e.preventDefault();startRace();}\n});\nwindow.addEventListener(\'keyup\',function(e){var k=KEYMAP[e.key];if(k)keys[k]=false;});\nwindow.addEventListener(\'blur\',function(){keys.left=keys.right=keys.up=keys.down=false;});\ndocument.addEventListener(\'visibilitychange\',function(){if(document.hidden)pauseRace();});\nfunction bindTouch(id,k){\n  var el=$(id);\n  function on(e){e.preventDefault();keys[k]=true;el.classList.add(\'on\');}\n  function off(e){e.preventDefault();keys[k]=false;el.classList.remove(\'on\');}\n  el.addEventListener(\'pointerdown\',on);\n  [\'pointerup\',\'pointercancel\',\'pointerleave\'].forEach(function(ev){el.addEventListener(ev,off);});\n}\nbindTouch(\'tLeft\',\'left\');bindTouch(\'tRight\',\'right\');bindTouch(\'tGas\',\'up\');bindTouch(\'tBrake\',\'down\');\n\nfunction click(id,fn){$(id).addEventListener(\'click\',function(){fn();if(document.activeElement&&document.activeElement.blur&&id!==\'toSelect\')document.activeElement.blur();});}\nclick(\'toSelect\',function(){state=\'select\';showScreen(\'select\');buttons();});\nclick(\'backHome\',function(){state=\'menu\';showScreen(\'home\');buttons();});\nclick(\'confirmCar\',confirmCar);\nclick(\'bStart\',startRace);click(\'bPause\',pauseRace);click(\'bResume\',resumeRace);\nclick(\'bRestart\',restartRace);click(\'bNew\',newRace);\nclick(\'resRestart\',restartRace);click(\'resNew\',newRace);\n\n/* ---------- boot ---------- */\nbuildSelect();renderBoards();attractGame();buttons();startLoop();\n})();\n</script>\n</body></html>'

def car_lines():
    return "\n".join(
        f"- {c['name']}: speed {c['speed']}, acceleration {c['accel']}, handling {c['handling']}"
        for c in CARS
    )


SYSTEM_PROMPT = f"""You are the AI Racing Coach inside the browser game ULTIMATE STREET RACER.
Be friendly, concise (under 150 words) and practical. Only discuss the game, cars and racing tips.

GAME FACTS
- Race = 3 laps (2400 m each). 3 lives. Crashing into cones, barrels or traffic costs a life.
- Controls: Left/Right arrows (or A/D) steer, Up accelerate, Down brake, P pause. Touch buttons on phones.
- Scoring: +25 per car passed, +10 per obstacle avoided, +500 per lap, speed points,
  finish bonus = 1000 + time bonus + 200 per life left. Grades: S no crashes, A one, B two, C three.
- Traffic gets faster and denser each level. Hugging the barrier slows you down.
- Ratings are 1-10: speed = top speed, acceleration = how quickly you reach it, handling = steering response.

THE 20 CARS
{car_lines()}
"""


def offline_reply(question):
    q = question.lower()
    if any(w in q for w in ("car", "recommend", "best", "choose", "pick")):
        fast = max(CARS, key=lambda c: c["speed"])
        quick = max(CARS, key=lambda c: c["accel"])
        agile = max(CARS, key=lambda c: c["handling"])
        return (
            f"Car tips: **{fast['name']}** has top speed, **{quick['name']}** accelerates fastest, "
            f"and **{agile['name']}** handles best. Beginners should favor handling (8+)."
        )
    if any(w in q for w in ("score", "point")):
        return "Scoring: +25 per car passed, +10 per obstacle avoided, +500 per lap, speed points, and a finish bonus."
    return (
        "Racing tips: tap steering instead of holding it, brake before busy sections, "
        "stay in the middle lane for the widest escape routes, and avoid the barriers."
    )


def get_ai_reply(question, history):
    api_key = ""
    try:
        api_key = st.secrets.get("GROQ_API_KEY", "")
    except Exception:
        pass
    api_key = api_key or os.getenv("GROQ_API_KEY", "")

    if not api_key or Groq is None:
        return offline_reply(question) + "\n\n_AI coach is offline: add `GROQ_API_KEY` in Streamlit Secrets to enable Groq. The game still works._"

    messages = [{"role": "system", "content": SYSTEM_PROMPT}]
    for item in history[-6:]:
        messages.append({"role": "user", "content": item["question"]})
        messages.append({"role": "assistant", "content": item["answer"]})
    messages.append({"role": "user", "content": question[:MAX_QUESTION_CHARS]})

    try:
        client = Groq(api_key=api_key, timeout=GROQ_TIMEOUT_SECONDS, max_retries=1)
        response = client.chat.completions.create(
            model=GROQ_MODEL,
            messages=messages,
            max_tokens=400,
            temperature=0.6,
        )
        return (response.choices[0].message.content or "").strip() or "Try asking that another way."
    except Exception as exc:
        name = type(exc).__name__
        if "Authentication" in name:
            return "Groq rejected the API key. Check the `GROQ_API_KEY` value in Streamlit Secrets."
        if "RateLimit" in name:
            return "Groq rate limit reached. Wait a little and try again."
        if "Timeout" in name:
            return "The AI coach timed out. Please try again."
        return f"Groq AI error ({name}). Check your API key, model name, and Groq account."


st.markdown(
    """
    <style>
    .stApp { background: radial-gradient(circle at top, #1b1250 0%, #07070f 65%); color: #e8eaff; }
    h1 { color: #00f0ff; }
    [data-testid="stSidebar"] { background: #12122b; }
    </style>
    """,
    unsafe_allow_html=True,
)

st.title("🏎️ Ultimate Street Racer")
st.caption("Choose one of 20 cars, race 3 laps, dodge traffic, and climb the leaderboard.")

left, right = st.columns([3, 1], gap="large")
with left:
    st.subheader("🎮 Race")
    page = GAME_HTML.replace("__CARS_JSON__", json.dumps(CARS))
    components.html(page, height=800, scrolling=False)
    st.caption("Click inside the game to focus it. Use ← / → or A / D to steer, ↑ to accelerate, ↓ to brake, and P to pause.")

with right:
    st.subheader("🤖 AI Racing Coach")
    st.caption(f"Model: `{GROQ_MODEL}`")
    if "coach_history" not in st.session_state:
        st.session_state.coach_history = []

    for item in st.session_state.coach_history[-6:]:
        with st.chat_message("user"):
            st.markdown(item["question"])
        with st.chat_message("assistant"):
            st.markdown(item["answer"])

    with st.form("coach_form", clear_on_submit=True):
        question = st.text_input(
            "Ask the coach",
            placeholder="Which car suits aggressive driving?",
            max_chars=MAX_QUESTION_CHARS,
        )
        submitted = st.form_submit_button("Ask coach", use_container_width=True)

    if submitted and question.strip():
        clean_question = question.strip()[:MAX_QUESTION_CHARS]
        with st.spinner("The coach is thinking..."):
            answer = get_ai_reply(clean_question, st.session_state.coach_history)
        st.session_state.coach_history.append(
            {"question": clean_question, "answer": answer}
        )
        st.session_state.coach_history = st.session_state.coach_history[-12:]
        st.rerun()

    if st.button("Clear chat", use_container_width=True):
        st.session_state.coach_history = []
        st.rerun()

st.divider()
st.caption("Your Groq API key stays on the server. Never paste it into this code or into the public app.")
